using CarCareTracker.External.Interfaces;
using CarCareTracker.Models;
using Npgsql;
using System.Text.Json;

namespace CarCareTracker.External.Implementations
{
    public class PGUserSessionDataAccess : IUserSessionDataAccess
    {
        private NpgsqlDataSource pgDataSource;
        private readonly ILogger<PGUserSessionDataAccess> _logger;
        private static string tableName = "user_sessions";
        public PGUserSessionDataAccess(IConfiguration config, ILogger<PGUserSessionDataAccess> logger)
        {
            pgDataSource = NpgsqlDataSource.Create(config["POSTGRES_CONNECTION"] ?? string.Empty);
            _logger = logger;
            try
            {
                string initCMD = $"CREATE SCHEMA IF NOT EXISTS app; " +
                    $"CREATE TABLE IF NOT EXISTS app.{tableName} (id INT GENERATED BY DEFAULT AS IDENTITY primary key, userId INT not null, expiresAt TIMESTAMPTZ not null, revokedAt TIMESTAMPTZ null, data jsonb not null); " +
                    $"CREATE INDEX IF NOT EXISTS {tableName}_user_idx ON app.{tableName} (userId)";
                using (var ctext = pgDataSource.CreateCommand(initCMD))
                {
                    ctext.ExecuteNonQuery();
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex.Message);
            }
        }
        private static object Utc(DateTime? value) => value.HasValue ? DateTime.SpecifyKind(value.Value, DateTimeKind.Utc) : DBNull.Value;
        public UserSession? GetSessionById(int sessionId)
        {
            return Query($"SELECT data FROM app.{tableName} WHERE id = @id", x => x.AddWithValue("id", sessionId)).FirstOrDefault();
        }
        public List<UserSession> GetSessionsByUser(int userId)
        {
            return Query($"SELECT data FROM app.{tableName} WHERE userId = @userId ORDER BY id DESC", x => x.AddWithValue("userId", userId));
        }
        public bool SaveSession(UserSession session)
        {
            try
            {
                if (session.Id == default)
                {
                    string cmd = $"INSERT INTO app.{tableName} (userId, expiresAt, revokedAt, data) VALUES(@userId, @expiresAt, @revokedAt, CAST(@data AS jsonb)) RETURNING id";
                    using (var ctext = pgDataSource.CreateCommand(cmd))
                    {
                        AddColumns(ctext.Parameters, session);
                        session.Id = Convert.ToInt32(ctext.ExecuteScalar());
                    }
                }
                //the id is part of the stored document, so it is written once more after an insert.
                string cmdU = $"UPDATE app.{tableName} SET userId = @userId, expiresAt = @expiresAt, revokedAt = @revokedAt, data = CAST(@data AS jsonb) WHERE id = @id";
                using (var ctextU = pgDataSource.CreateCommand(cmdU))
                {
                    ctextU.Parameters.AddWithValue("id", session.Id);
                    AddColumns(ctextU.Parameters, session);
                    return ctextU.ExecuteNonQuery() > 0;
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex.Message);
                return false;
            }
        }
        private static void AddColumns(NpgsqlParameterCollection parameters, UserSession session)
        {
            parameters.AddWithValue("userId", session.UserId);
            parameters.AddWithValue("expiresAt", Utc(session.ExpiresUtc));
            parameters.AddWithValue("revokedAt", Utc(session.RevokedUtc));
            parameters.AddWithValue("data", JsonSerializer.Serialize(session));
        }
        public int RevokeSessionsForUser(int userId, DateTime revokedUtc, int? exceptSessionId)
        {
            int count = 0;
            foreach (var session in GetSessionsByUser(userId).Where(x => x.RevokedUtc == null && x.Id != exceptSessionId))
            {
                session.RevokedUtc = revokedUtc;
                if (SaveSession(session))
                {
                    count++;
                }
            }
            return count;
        }
        public int DeleteSessionsEndedBefore(DateTime cutoffUtc)
        {
            try
            {
                string cmd = $"DELETE FROM app.{tableName} WHERE expiresAt < @cutoff OR revokedAt < @cutoff";
                using (var ctext = pgDataSource.CreateCommand(cmd))
                {
                    ctext.Parameters.AddWithValue("cutoff", Utc(cutoffUtc));
                    return ctext.ExecuteNonQuery();
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex.Message);
                return 0;
            }
        }
        private List<UserSession> Query(string cmd, Action<NpgsqlParameterCollection> addParameters)
        {
            var results = new List<UserSession>();
            try
            {
                using (var ctext = pgDataSource.CreateCommand(cmd))
                {
                    addParameters(ctext.Parameters);
                    using (NpgsqlDataReader reader = ctext.ExecuteReader())
                        while (reader.Read())
                        {
                            var session = JsonSerializer.Deserialize<UserSession>(reader["data"] as string ?? "{}");
                            if (session != null)
                            {
                                results.Add(session);
                            }
                        }
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex.Message);
            }
            return results;
        }
    }
}
